import React, { useState, useRef, useEffect } from "react";

const ClientForm = ({ onSave, existingTags = [] }) => {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [tags, setTags] = useState([]);
  const [tagInput, setTagInput] = useState("");
  const [showDropdown, setShowDropdown] = useState(false);
  const [filteredTags, setFilteredTags] = useState([]);
  const inputRef = useRef(null);

  // Filter existing tags based on input
  useEffect(() => {
    if (tagInput.trim()) {
      const filtered = existingTags.filter(tag => 
        tag.toLowerCase().includes(tagInput.toLowerCase()) && !tags.includes(tag)
      );
      setFilteredTags(filtered);
      setShowDropdown(filtered.length > 0);
    } else {
      setFilteredTags([]);
      setShowDropdown(false);
    }
  }, [tagInput, existingTags, tags]);

  const handleTagInputChange = (e) => {
    setTagInput(e.target.value);
  };

  const addTag = (tag) => {
    if (tag.trim() && !tags.includes(tag.trim())) {
      setTags([...tags, tag.trim()]);
      setTagInput("");
      setShowDropdown(false);
    }
  };

  const handleTagInputKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (tagInput.trim()) {
        addTag(tagInput);
      }
    } else if (e.key === 'Escape') {
      setShowDropdown(false);
      setTagInput("");
    }
  };

  const removeTag = (tagToRemove) => {
    setTags(tags.filter(tag => tag !== tagToRemove));
  };

  const selectFromDropdown = (tag) => {
    addTag(tag);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSave({ name, email, phone, tags });
    setName("");
    setEmail("");
    setPhone("");
    setTags([]);
    setTagInput("");
    setShowDropdown(false);
  };

  return (
    <form className="space-y-4" onSubmit={handleSubmit}>
      <input 
        className="border border-gray-300 p-3 w-full rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" 
        placeholder="Full Name" 
        value={name} 
        onChange={e => setName(e.target.value)} 
        required 
      />
      <input 
        className="border border-gray-300 p-3 w-full rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" 
        placeholder="Email Address" 
        value={email} 
        onChange={e => setEmail(e.target.value)} 
        required 
      />
      <input 
        className="border border-gray-300 p-3 w-full rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" 
        placeholder="Contact Number" 
        value={phone} 
        onChange={e => setPhone(e.target.value)} 
      />

      {/* Custom Tags Input */}
      <div className="space-y-2">
        <label className="block text-sm font-medium text-gray-700">Tags</label>
        <div className="relative">
          <input
            ref={inputRef}
            type="text"
            className="border border-gray-300 p-3 w-full rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            placeholder="Add tags (press Enter to add)"
            value={tagInput}
            onChange={handleTagInputChange}
            onKeyDown={handleTagInputKeyDown}
            onFocus={() => tagInput.trim() && setShowDropdown(filteredTags.length > 0)}
          />

          {/* Dropdown for existing tags */}
          {showDropdown && filteredTags.length > 0 && (
            <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-lg shadow-lg max-h-40 overflow-y-auto">
              {filteredTags.map((tag, index) => (
                <button
                  key={index}
                  type="button"
                  className="w-full text-left px-4 py-2 hover:bg-gray-100 focus:bg-gray-100 focus:outline-none"
                  onClick={() => selectFromDropdown(tag)}
                >
                  {tag}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Selected Tags Display */}
        {tags.length > 0 && (
          <div className="flex flex-wrap gap-2 mt-2">
            {tags.map((tag, index) => (
              <span
                key={index}
                className="inline-flex items-center px-3 py-1 rounded-full text-sm bg-blue-100 text-blue-800"
              >
                {tag}
                <button
                  type="button"
                  onClick={() => removeTag(tag)}
                  className="ml-2 text-blue-600 hover:text-blue-800 focus:outline-none"
                >
                  ×
                </button>
              </span>
            ))}
          </div>
        )}

        <p className="text-xs text-gray-500">
          Type to add new tags or select from existing ones. Press Enter to add.
        </p>
      </div>

      <button 
        className="w-full bg-blue-600 text-white px-4 py-3 rounded-lg hover:bg-blue-700 transition-colors font-medium" 
        type="submit"
      >
        Save Client
      </button>
    </form>
  );
};

export default ClientForm;
